const feedItems = pages.map((page) => `<item><title>${page.title.replace(/&/g, "&amp;")}</title><link>${siteUrl}/${page.path}</link><guid isPermaLink="true">${siteUrl}/${page.path}</guid><pubDate>${pubDate}</pubDate><category>${page.category}</category><description>${page.description.replace(/&/g, "&amp;")}</description></item>`).join("\n");
const feedBlock = `<!-- DAILY 2026-08-26 FEED START -->\n${feedItems}\n<!-- DAILY 2026-08-26 FEED END -->\n`;
feed = feed.includes("<!-- DAILY 2026-08-25 FEED START -->") ? feed.replace("<!-- DAILY 2026-08-25 FEED START -->", `${feedBlock}    <!-- DAILY 2026-08-25 FEED START -->`) : feed.replace(/\s*<item>/, `\n${feedBlock}<item>`);
writeFileSync(join(root, "feed.xml"), feed);

let sitemap = readFileSync(join(root, "sitemap.xml"), "utf8");
for (const path of ["", "essays.html", "field-guides.html"]) { const url = `${siteUrl}/${path}`, re = new RegExp(`(<loc>${url.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}<\\/loc><lastmod>)[^<]+`); sitemap = sitemap.replace(re, `$1${published}`); }
sitemap = sitemap.replace(/\s*<!-- DAILY 2026-08-26 SITEMAP START -->[\s\S]*?<!-- DAILY 2026-08-26 SITEMAP END -->\s*/g, "");
const urls = pages.map((page) => `<url><loc>${siteUrl}/${page.path}</loc><lastmod>${published}</lastmod><changefreq>monthly</changefreq><priority>0.8</priority></url>`).join("\n");
sitemap = sitemap.replace("</urlset>", `\n<!-- DAILY 2026-08-26 SITEMAP START -->\n${urls}\n<!-- DAILY 2026-08-26 SITEMAP END -->\n</urlset>`);
writeFileSync(join(root, "sitemap.xml"), sitemap);

let llms = readFileSync(join(root, "llms.txt"), "utf8").replace(/\n?## Daily publication 2026-08-26[\s\S]*?(?=\n## |$)/g, "");
llms += `\n\n## Daily publication 2026-08-26\n- ${essay.title}: ${siteUrl}/${essay.path}\n- ${guide.title}: ${siteUrl}/${guide.path}\n`;
writeFileSync(join(root, "llms.txt"), llms);

const creditPath = join(root, "assets", "visuals", "credits.json");
const credits = existsSync(creditPath) ? JSON.parse(readFileSync(creditPath, "utf8")) : { assets: [] };
credits.generated = published;
credits.assets = credits.assets.filter((item) => item.path !== "/assets/visuals/repetition-truth-check.svg");
for (const page of pages) { const item = { path: page.image, creator: "Life in the Simulation Editorial Desk", source: "Original editorial illustration", license: "Copyright Life in the Simulation" }; const i = credits.assets.findIndex((x) => x.path === item.path); if (i >= 0) credits.assets[i] = item; else credits.assets.push(item); }
writeFileSync(creditPath, `${JSON.stringify(credits, null, 2)}\n`);
console.log(`Published ${pages.length} pages for ${published} into ${root}.`);
